from moler.util.moler_test import MolerTest
from taf.ul.sc.unix_functionality import UnixFunctionality
from taf.ul.sc.util.helpers import log_info_to_console

from typing import Any

class Syslog(UnixFunctionality):
    """
    Class with keywords for the Gnb Syslog device.
    """

    def __init__(self,
                 device_name='GNB0_SYSLOG',     # type: 'Optional[str]'
                 device=None,                   # type: 'Optional[UnixSyslog]'
                 autoconnect=False,             # type: 'Optional[bool]'
                 get_device=False               # type: 'Optional[bool]'
                 ):
        self.syslog_event = []
        super(Syslog, self).__init__(device_name=device_name, device=device,
                                     autoconnect=autoconnect, get_device=get_device)

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_syslog(self):
        """
        Creates the Syslog device object based on the given device name.
        :return: nothing
        """
        MolerTest.info("Connecting to {} device".format(self.name))
        self.connect()

        MolerTest.steps_end()
    # TODO: add collback variable. If end test is there then break_test from scenario runner should be used.
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def start_syslog_observer(self, patterns=(), match='any', mode='background', timeout=60, till_occurs_times="1",
                              break_test=False, break_function=None):
        """
        Starts observing syslog connection for passed pattern.
        :param patterns: regular expression pattern
        :param match: type of awaiting: any, all, sequence
        :param mode: type of awaiting: any, all, sequence
        :param timeout: timeout for running syslog
        :param till_occurs_times: How many times pattern should occurs to stop a observer
        :param break_test: if True, the test will be stopped when pattern is found
        :param break_function: function to be called to break the test
        :return: nothing
        """
        MolerTest.info("Start Syslog Observer for PATTERN: {}".format(patterns))
        # different behaviour if pattern is list or dict. Pattern takes till_occurs_times and dict has it defined inside
        # {pattern: till_occurs_times}
        parsed_patterns = {}
        if isinstance(patterns, list):
            parsed_patterns = {pattern: till_occurs_times for pattern in patterns}
        elif isinstance(patterns, dict):
            parsed_patterns = patterns

        self._run_syslog_events(break_function, break_test, match, mode, parsed_patterns, timeout)
        MolerTest.steps_end()

    def _run_syslog_events(self, break_function, break_test: bool, match: str, mode: str,
                           parsed_patterns: dict[Any, Any] | dict[Any, str] | dict, timeout: int):
        for pattern, till_occurs_time in parsed_patterns.items():
            MolerTest.info("Observer for pattern {} till time {} starting".format(pattern, till_occurs_time))
            syslog_event = self.device.get_event(
                event_name="wait4",
                event_params={"detect_patterns": [pattern],
                              "till_occurs_times": int(till_occurs_time), "match": match}
            )
            syslog_event.add_event_occurred_callback(
                callback=Syslog._notify_event_occurred,
                callback_params={
                    "msg": f"Observer found {pattern} {till_occurs_time} time(s).",
                    "event": syslog_event,
                    "break_test": break_test,
                    "break_function": break_function
                }
            )
            self.syslog_event.append(syslog_event)
            if mode in 'foreground':
                syslog_event(timeout=timeout)
            else:
                syslog_event.start(timeout=timeout)

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def stop_syslog_observer(self):
        """
        Stops syslog observer.
        :return: nothing
        """
        for syslog_event in self.syslog_event:
            syslog_event.cancel()
        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def check_if_pattern_occurred(self):
        """
        Checks if pattern occurred in syslog and raise error if not occurred.
        :return: nothing
        """
        # TBD More accurate message
        for syslog_event in self.syslog_event:
            cancelled = syslog_event.cancelled()
            if cancelled:
                MolerTest.error("Pattern: [{}] did not occur so Test Case is FAILED".format(
                    syslog_event.detect_patterns))
            else:
                MolerTest.info("Pattern: [{}] occurred so Test Case is PASSED".format(
                    syslog_event.detect_patterns))

        MolerTest.steps_end()

    @staticmethod
    def _notify_event_occurred(msg, event, break_test=False, break_function=None):
        """
        Callback function. Prints pattern and caught line
        :param msg: String to be printed
        :param event: event object
        :return: nothing
        """
        last_occurrence = event.get_last_occurrence()
        # check if event.counter is defined
        if not hasattr(event, "counter"):
            event.counter = 0
        event.counter += 1
        MolerTest.warning(
            msg="Occurrence found \"{}\". Number of occurrences is {}".format(
          last_occurrence['matched'],
                event.counter
            )
        )
        if hasattr(event, "copy_compiled_patterns") and \
                len(event.copy_compiled_patterns) == len(event.detect_patterns):
            MolerTest.info("Cycle number {} was finished".format(event.finished_cycles))
        if event.done():
            log_info_to_console(msg=msg)
            MolerTest.warning(msg=msg)
            if break_test and break_function:
                log_info_to_console(f"Breaking test as pattern {event.detect_patterns} was found and break_test is set to True")
                MolerTest.info("All cycles were finished. Stopping Scenario.")
                log_info_to_console("All cycles were finished. Stopping Scenario.")
                break_function()

    def get_events(self):
        """
        Returns list of syslog events.
        :return: list of syslog events
        """
        return self.syslog_event
